static inline const struct ObjectEventGraphicsInfo *SpeciesToSwimmingGraphicsInfo(enum Species species, bool32 shiny, bool32 female)
{
    if (species < NUM_SPECIES && gSwimmingMonGraphicsInfo[species].images != NULL)
        return &gSwimmingMonGraphicsInfo[species];
    return NULL;
}

